boltOn.example:
t3template.addControl({ id: 'glow', label: 'Amount', type: 'slider', min: 0, max: 1, step: 0.01, default: 0.4, panel: 'Glow' });
t3template.addControl({ id: 'radius', label: 'Radius', type: 'slider', min: 2, max: 60, step: 1, default: 18, panel: 'Glow' });
t3template.addControl({ id: 'credit', label: 'Credit', type: 'text', placeholder: 'Photo credit', default: '', panel: 'Glow' });
t3template.addImageStage('glow', ({ context, width, height, scale, copy, crop }, c) => {
  if (c.glow > 0) {
    const soft = copy();
    context.globalCompositeOperation = 'screen';
    context.globalAlpha = c.glow;
    context.filter = `blur(${c.radius * scale}px)`;
    context.drawImage(soft, 0, 0);
  }
  if (c.credit) {
    context.globalCompositeOperation = 'source-over';
    context.globalAlpha = 0.8;
    context.filter = 'none';
    context.fillStyle = '#ffffff';
    context.font = `${Math.round(width * 0.02)}px sans-serif`;
    context.textAlign = 'right';
    context.fillText(c.credit, crop.x + crop.w - width * 0.02, crop.y + crop.h - width * 0.02);
  }
});
t3template.addToolbarButton('Glow Off', (t) => t.setValues({ controls: { glow: 0 } }), { shortcut: 'shift+g' });
